dashboard.definition:
{
	"title": "Asset Inventory",
	"description": "Unified device inventory from Catalyst Center, Meraki, IOS, ASA/FTD, ISE, F5, and Windows/AD",
	"inputs": {
		"input_device_type": {
			"options": {
				"defaultValue": [
					"*"
				],
				"items": [
					{
						"label": "All",
						"value": "*"
					},
					{
						"label": "AP",
						"value": "AP"
					},
					{
						"label": "Firewall",
						"value": "Firewall"
					},
					{
						"label": "Gateway",
						"value": "Gateway"
					},
					{
						"label": "Load Balancer",
						"value": "Load Balancer"
					},
					{
						"label": "Network Device",
						"value": "Network Device"
					},
					{
						"label": "Router",
						"value": "Router"
					},
					{
						"label": "Sensor",
						"value": "Sensor"
					},
					{
						"label": "Server",
						"value": "Server"
					},
					{
						"label": "Switch",
						"value": "Switch"
					},
					{
						"label": "WLC",
						"value": "WLC"
					}
				],
				"token": "filter_type"
			},
			"title": "Device Type",
			"type": "input.multiselect"
		},
		"input_mgmt_source": {
			"options": {
				"defaultValue": [
					"*"
				],
				"items": [
					{
						"label": "All",
						"value": "*"
					},
					{
						"label": "Catalyst Center",
						"value": "Catalyst Center"
					},
					{
						"label": "Meraki Dashboard",
						"value": "Meraki Dashboard"
					},
					{
						"label": "IOS Syslog",
						"value": "IOS Syslog"
					},
					{
						"label": "Firewall Syslog",
						"value": "Firewall Syslog"
					},
					{
						"label": "ISE NAD",
						"value": "ISE NAD"
					},
					{
						"label": "F5 iControl",
						"value": "F5 iControl"
					},
					{
						"label": "Windows/AD",
						"value": "Windows/AD"
					}
				],
				"token": "filter_source"
			},
			"title": "Management Source",
			"type": "input.multiselect"
		},
		"input_time_range": {
			"options": {
				"defaultValue": "-4h@m,now",
				"token": "time_tok"
			},
			"title": "Time Selector",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "-24h@h",
						"latest": "now"
					}
				}
			}
		},
		"tokens": {
			"default": {}
		}
	},
	"visualizations": {
		"viz_about_bg": {
			"options": {
				"fillColor": "#131a23",
				"rx": 10,
				"strokeColor": "rgba(100,158,245,0.28)",
				"strokeOpacity": 1,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_box_gap_analysis": {
			"options": {
				"fillColor": "#131a23",
				"rx": 10,
				"strokeColor": "rgba(100,158,245,0.28)",
				"strokeOpacity": 1,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_box_gap_fw": {
			"options": {
				"fillColor": "#131a23",
				"rx": 10,
				"strokeColor": "rgba(100,158,245,0.28)",
				"strokeOpacity": 1,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_box_gap_kpi": {
			"options": {
				"fillColor": "#131a23",
				"rx": 10,
				"strokeColor": "rgba(100,158,245,0.28)",
				"strokeOpacity": 1,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_box_inv_charts": {
			"options": {
				"fillColor": "#131a23",
				"rx": 10,
				"strokeColor": "rgba(100,158,245,0.28)",
				"strokeOpacity": 1,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_box_inv_kpi": {
			"options": {
				"fillColor": "#131a23",
				"rx": 10,
				"strokeColor": "rgba(100,158,245,0.28)",
				"strokeOpacity": 1,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_box_inv_location": {
			"options": {
				"fillColor": "#131a23",
				"rx": 10,
				"strokeColor": "rgba(100,158,245,0.28)",
				"strokeOpacity": 1,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_box_inv_table": {
			"options": {
				"fillColor": "#131a23",
				"rx": 10,
				"strokeColor": "rgba(100,158,245,0.28)",
				"strokeOpacity": 1,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_by_family": {
			"dataSources": {
				"primary": "ds_count_by_family"
			},
			"options": {
				"backgroundColor": "#131a23",
				"legendDisplay": "off",
				"xAxisVisibility": "show",
				"yAxisVisibility": "show",
				"seriesColors": [
					"#649ef5",
					"#4cbf7f",
					"#f0c243",
					"#fa5762",
					"#9ca6ff",
					"#9b5ff5",
					"#049fd9",
					"#00bceb",
					"#f7782f"
				]
			},
			"title": "Devices by Family",
			"type": "splunk.bar"
		},
		"viz_by_location": {
			"dataSources": {
				"primary": "ds_count_by_location"
			},
			"options": {
				"backgroundColor": "#131a23",
				"legendDisplay": "off",
				"xAxisVisibility": "show",
				"yAxisVisibility": "show",
				"seriesColors": [
					"#649ef5",
					"#4cbf7f",
					"#f0c243",
					"#fa5762",
					"#9ca6ff",
					"#9b5ff5",
					"#049fd9",
					"#00bceb",
					"#f7782f"
				]
			},
			"title": "Devices by Location",
			"type": "splunk.bar"
		},
		"viz_by_source": {
			"dataSources": {
				"primary": "ds_filtered_count_by_source"
			},
			"options": {
				"backgroundColor": "#131a23",
				"showDonutHole": true,
				"seriesColors": [
					"#649ef5",
					"#4cbf7f",
					"#f0c243",
					"#fa5762",
					"#9ca6ff",
					"#9b5ff5",
					"#049fd9",
					"#00bceb",
					"#f7782f"
				]
			},
			"title": "Devices by Management Source",
			"type": "splunk.pie"
		},
		"viz_by_type": {
			"dataSources": {
				"primary": "ds_filtered_count_by_type"
			},
			"options": {
				"backgroundColor": "#131a23",
				"showDonutHole": true,
				"seriesColors": [
					"#649ef5",
					"#4cbf7f",
					"#f0c243",
					"#fa5762",
					"#9ca6ff",
					"#9b5ff5",
					"#049fd9",
					"#00bceb",
					"#f7782f"
				]
			},
			"title": "Devices by Type",
			"type": "splunk.pie"
		},
		"viz_firewall_gap_table": {
			"dataSources": {
				"primary": "ds_firewall_gap"
			},
			"description": "All known firewalls — which are sending FTD/ASA/eStreamer data to Splunk",
			"options": {
				"backgroundColor": "#131a23",
				"count": 20,
				"headerVisibility": "fixed",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBackgroundColorsByIndex)",
					"headerBackgroundColor": "#1c2738",
					"headerColor": "#ecf0f5"
				},
				"fontSize": "small",
				"columnFormat": {
					"data_status": {
						"rowBackgroundColors": "> table | seriesByName(\"data_status\") | matchValue(viz_firewall_gap_table_datastatus_colors)"
					}
				}
			},
			"title": "Firewall Data Status",
			"type": "splunk.table",
			"context": {
				"viz_firewall_gap_table_datastatus_colors": [
					{
						"match": "missing",
						"value": "rgba(214,69,80,0.35)"
					},
					{
						"match": "Missing",
						"value": "rgba(214,69,80,0.35)"
					},
					{
						"match": "No data",
						"value": "rgba(214,69,80,0.35)"
					},
					{
						"match": "NO DATA",
						"value": "rgba(214,69,80,0.35)"
					},
					{
						"match": "absent",
						"value": "rgba(214,69,80,0.35)"
					},
					{
						"match": "present",
						"value": "rgba(110,190,74,0.15)"
					},
					{
						"match": "Present",
						"value": "rgba(110,190,74,0.15)"
					},
					{
						"match": "OK",
						"value": "rgba(110,190,74,0.15)"
					}
				]
			}
		},
		"viz_fw_header": {
			"options": {
				"fontColor": "#f0c243",
				"fontSize": "small",
				"markdown": "### Firewall Coverage",
				"backgroundColor": "#131a23"
			},
			"type": "splunk.markdown"
		},
		"viz_fw_kpi_expected": {
			"dataSources": {
				"primary": "ds_fw_kpi_expected"
			},
			"options": {
				"backgroundColor": "#131a23",
				"majorColor": "#049fd9",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"trendColor": "#649ef5"
			},
			"title": "FW Expected",
			"type": "splunk.singlevalue",
			"description": "Total firewalls expected based on inventory records"
		},
		"viz_fw_kpi_gap": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 1,
						"value": "#4cbf7f"
					},
					{
						"from": 1,
						"to": 5,
						"value": "#f0c243"
					},
					{
						"from": 5,
						"value": "#fa5762"
					}
				]
			},
			"dataSources": {
				"primary": "ds_fw_kpi_gap"
			},
			"options": {
				"backgroundColor": "#131a23",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"trendColor": "#649ef5"
			},
			"title": "FW Missing",
			"type": "splunk.singlevalue",
			"description": "Firewalls in inventory with no data in Splunk"
		},
		"viz_fw_kpi_pairs": {
			"dataSources": {
				"primary": "ds_fw_kpi_pairs"
			},
			"options": {
				"backgroundColor": "#131a23",
				"majorColor": "#049fd9",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"trendColor": "#649ef5"
			},
			"title": "HA Pairs Detected",
			"type": "splunk.singlevalue",
			"description": "Estimated firewall high-availability pairs detected"
		},
		"viz_fw_kpi_sending": {
			"dataSources": {
				"primary": "ds_fw_kpi_sending"
			},
			"options": {
				"backgroundColor": "#131a23",
				"majorColor": "#4cbf7f",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"trendColor": "#649ef5"
			},
			"title": "FW Sending Data",
			"type": "splunk.singlevalue",
			"description": "Firewalls actively sending syslog or event data"
		},
		"viz_gap_header_bg": {
			"options": {
				"fillColor": "#1c2738",
				"rx": 10,
				"strokeColor": "rgba(100,158,245,0.28)",
				"strokeOpacity": 1,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_gap_kpi_nodata": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 1,
						"value": "#4cbf7f"
					},
					{
						"from": 1,
						"to": 10,
						"value": "#f0c243"
					},
					{
						"from": 10,
						"value": "#fa5762"
					}
				]
			},
			"dataSources": {
				"primary": "ds_gap_kpi_nodata"
			},
			"options": {
				"backgroundColor": "#131a23",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"trendColor": "#649ef5"
			},
			"title": "No Data",
			"type": "splunk.singlevalue",
			"description": "Devices with no data received in the time range"
		},
		"viz_gap_kpi_pct": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 50,
						"value": "#fa5762"
					},
					{
						"from": 50,
						"to": 80,
						"value": "#f0c243"
					},
					{
						"from": 80,
						"value": "#4cbf7f"
					}
				]
			},
			"dataSources": {
				"primary": "ds_gap_kpi_pct"
			},
			"options": {
				"backgroundColor": "#131a23",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"unit": "%",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"trendColor": "#649ef5"
			},
			"title": "Coverage",
			"type": "splunk.singlevalue",
			"description": "Percentage of inventory devices sending data"
		},
		"viz_gap_kpi_sending": {
			"dataSources": {
				"primary": "ds_gap_kpi_sending"
			},
			"options": {
				"backgroundColor": "#131a23",
				"majorColor": "#4cbf7f",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"trendColor": "#649ef5"
			},
			"title": "Sending Data",
			"type": "splunk.singlevalue",
			"description": "Devices actively sending telemetry or log data"
		},
		"viz_gap_kpi_total": {
			"dataSources": {
				"primary": "ds_gap_kpi_total"
			},
			"options": {
				"backgroundColor": "#131a23",
				"majorColor": "#049fd9",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"trendColor": "#649ef5"
			},
			"title": "Total Devices",
			"type": "splunk.singlevalue",
			"description": "Total devices evaluated for data coverage"
		},
		"viz_gap_nodata_table": {
			"dataSources": {
				"primary": "ds_gap_no_data"
			},
			"description": "These inventory devices have no matching events in any Splunk data source",
			"options": {
				"backgroundColor": "#131a23",
				"count": 20,
				"fontSize": "small",
				"headerVisibility": "fixed",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBackgroundColorsByIndex)",
					"headerBackgroundColor": "#1c2738",
					"headerColor": "#ecf0f5"
				},
				"showRowNumbers": true
			},
			"title": "Devices NOT Sending Data to Splunk",
			"type": "splunk.table"
		},
		"viz_gap_section": {
			"options": {
				"fillColor": "rgba(15,17,23,0.78)",
				"rx": 12,
				"strokeColor": "rgba(65,74,86,0.52)",
				"strokeOpacity": 1,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_gap_summary_bar": {
			"dataSources": {
				"primary": "ds_gap_summary"
			},
			"description": "Sending Data vs No Data per device family",
			"options": {
				"backgroundColor": "#131a23",
				"dataValuesDisplay": "all",
				"seriesColors": [
					"#fa5762",
					"#4cbf7f"
				],
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"title": "Coverage by Device Family",
			"type": "splunk.bar"
		},
		"viz_header_bg": {
			"options": {
				"fillColor": "#1c2738",
				"rx": 10,
				"strokeColor": "rgba(100,158,245,0.28)",
				"strokeOpacity": 1,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_info_charts": {
			"options": {
				"fontColor": "#ecf0f5",
				"fontSize": "small",
				"markdown": "### Metric Reference — Asset Inventory\n\n---\n\n**Total Devices** — Unique devices across all management sources\n\n**Known IP Addresses** — Devices with a known management IP\n\n**Known Serials** — Devices with a hardware serial number\n\n**Last Lookup Refresh** — Scheduled nightly at 02:05 AM\n\n---\n\n**Devices by Type** — Pie chart of device categories (switch, router, AP, firewall, etc.)\n\n**Devices by Management Source** — Which platform discovered each device\n\n**Devices by Family** — Hardware families (Catalyst 9300, Meraki MR, ASA 5500, etc.)\n\n**Devices by Location** — Device distribution across physical sites\n\n---\n\n**Full Inventory** — Searchable table with device name, type, IP, serial, site, source, and last-seen time",
				"backgroundColor": "#131a23"
			},
			"type": "splunk.markdown"
		},
		"viz_info_gap": {
			"options": {
				"fontColor": "#ecf0f5",
				"fontSize": "small",
				"markdown": "### Metric Reference — Data Coverage Gaps\n\n---\n\n**Total Devices** — Catalyst Center managed devices in the asset inventory\n\n**Sending Data** — Devices with live telemetry arriving in Splunk within the selected time range\n\n**No Data** — Devices that have never sent any data to Splunk\n\n**Coverage** — Percentage of managed devices with active data\n\n---\n\n**Coverage by Device Family** — Data coverage broken down by hardware family\n\n**Devices NOT Sending Data** — Detail table with first seen, last seen, and data status (Sending Data / Data Stopped / NO DATA)\n\n---\n\n**FW Sending Data** — Firewalls actively sending FTD/ASA/eStreamer data\n\n**FW Expected** — Expected firewall count from the asset inventory\n\n**FW Missing** — Gap between expected and sending firewalls\n\n**HA Pairs Detected** — High availability pair discovery\n\n**Firewall Data Status** — Per-firewall detail with sourcetypes, event count, first seen, and last seen",
				"backgroundColor": "#131a23"
			},
			"type": "splunk.markdown"
		},
		"viz_inv_section": {
			"options": {
				"fillColor": "rgba(15,17,23,0.78)",
				"rx": 12,
				"strokeColor": "rgba(65,74,86,0.52)",
				"strokeOpacity": 1,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_inventory_table": {
			"dataSources": {
				"primary": "ds_inventory_table"
			},
			"description": "Device Inventory Detail",
			"options": {
				"backgroundColor": "#131a23",
				"columnOrder": [
					"Device Name",
					"Type",
					"Family",
					"Platform",
					"IP Address",
					"Software",
					"Serial",
					"Location",
					"Source",
					"Health",
					"Compliance",
					"Last Seen"
				],
				"count": 50,
				"fontSize": "small",
				"headerVisibility": "fixed",
				"tableFormat": {
					"headerBackgroundColor": "#1c2738",
					"headerColor": "#ecf0f5",
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)"
				}
			},
			"title": "Full Inventory",
			"type": "splunk.table"
		},
		"viz_last_refresh": {
			"dataSources": {
				"primary": "ds_last_refresh"
			},
			"options": {
				"backgroundColor": "#131a23",
				"majorColor": "#ecf0f5",
				"sparklineDisplay": "off",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"trendColor": "#649ef5"
			},
			"title": "Last Lookup Refresh",
			"type": "splunk.singlevalue",
			"description": "Most recent inventory lookup refresh timestamp"
		},
		"viz_p_hdr_bg": {
			"options": {
				"fillColor": "#1c2738",
				"rx": 10,
				"strokeColor": "rgba(100,158,245,0.28)",
				"strokeOpacity": 1,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_p_hdr_title": {
			"options": {
				"fontColor": "#649ef5",
				"markdown": "## Asset Inventory",
				"fontSize": "large",
				"backgroundColor": "#1c2738"
			},
			"type": "splunk.markdown"
		},
		"viz_total_devices": {
			"dataSources": {
